; Code patterns generated by MSVC for x64 (image relative addressing)
; assemble: nasm -f win64 msvc_patterns.asm

default rel
extern __ImageBase

section .data
global_array: dd 3, 1, 4, 1, 5, 9, 2, 6

section .text

; int rva_switch(int x) - jump table with image relative entries
global rva_switch
rva_switch:
        cmp ecx, 5
        ja .default
        lea rdx, [rel __ImageBase]
        movsxd rax, ecx
        mov ecx, [rdx+rax*4+.table wrt ..imagebase]
        add rcx, rdx
        jmp rcx
.case0: mov eax, 100
        ret
.case1: mov eax, 101
        ret
.case2: mov eax, 102
        ret
.case3: mov eax, 103
        ret
.case4: mov eax, 104
        ret
.case5: mov eax, 105
        ret
.default:
        mov eax, -1
        ret
        align 4, int3
.table: dd .case0 wrt ..imagebase, .case1 wrt ..imagebase, .case2 wrt ..imagebase
        dd .case3 wrt ..imagebase, .case4 wrt ..imagebase, .case5 wrt ..imagebase

; int rva_byte_switch(unsigned x) - byte index table + jump table
        align 16, int3
global rva_byte_switch
rva_byte_switch:
        cmp ecx, 15
        ja .default
        lea r8, [rel __ImageBase]
        mov eax, ecx
        movzx eax, byte [r8+rax+.btable wrt ..imagebase]
        mov ecx, [r8+rax*4+.table wrt ..imagebase]
        add rcx, r8
        jmp rcx
.c0:    mov eax, 10
        ret
.c1:    mov eax, 20
        ret
.c2:    mov eax, 30
        ret
.default:
        xor eax, eax
        ret
        align 4, int3
.table: dd .c0 wrt ..imagebase, .c1 wrt ..imagebase, .c2 wrt ..imagebase
.btable: db 0, 1, 2, 2, 1, 0, 0, 2, 1, 1, 2, 0, 0, 0, 1, 2

; int rva_array_sum(void) - array indexed relative to image base
        align 16, int3
global rva_array_sum
rva_array_sum:
        lea r9, [rel __ImageBase]
        xor eax, eax
        xor ecx, ecx
.loop:  add eax, [r9+rcx*4+global_array wrt ..imagebase]
        inc rcx
        cmp rcx, 8
        jb .loop
        ret
